{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "공영주차장에서 전기차 충전 시 1시간 초과 주차요금의 계산 방법",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "「서울특별시 주차장 설치 및 관리 조례」 제7조제1항제9호에 따르면, 「환경친화적 자동차의 개발 및 보급 촉진에 관한 법률」 제2조에 따른 전기자동차를 충전하는 경우 1시간 범위 내에서는 주차요금을 면제하고, 1시간을 초과한 때부터 부과되는 주차요금의 100분의 50을 할인한다.",
          "b_ids": "주차장:제7조제1항제9호"
        },
        {
          "a_text": "따라서 전기차 충전으로 1시간을 넘겨 주차한 경우, 1시간 초과 시점부터 부과되는 주차요금의 50%가 할인된 금액이 적용된다.",
          "b_ids": "주차장:제7조제1항제9호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
